1	import { readFileSync } from "node:fs";
2	import {
3	  transactScenario,
4	  type Customer,
5	  type Incident,
6	  type Item,
7	} from "./claim-office.js";
8	
9	/**
10	 * The wire shapes of the scenario document, as the published CLI schema names
11	 * them. They describe what arrives on stdin, not what MHPCO knows: the office's
12	 * own reading of a visit lives in claim-office.
13	 */
14	interface QuoteStep {
15	  op: "quote";
16	  items: Item[];
17	}
18	
19	interface ClaimStep {
20	  op: "claim";
21	  policy: number;
22	  incident: Incident;
23	}
24	
25	interface ScenarioDocument {
26	  customer: Customer;
27	  steps: (QuoteStep | ClaimStep)[];
28	}
29	
30	const STDIN_FD = 0;
31	
32	function readStdin(): string {
33	  return readFileSync(STDIN_FD, "utf8");
34	}
35	
36	function main(): void {
37	  const scenario = JSON.parse(readStdin()) as ScenarioDocument;
38	  process.stdout.write(
39	    JSON.stringify({ results: transactScenario(scenario) }),
40	  );
41	}
42	
43	try {
44	  main();
45	} catch (error) {
46	  process.stderr.write(`${(error as Error).message}\n`);
47	  process.exit(1);
48	}
