1	import { describe, expect, it } from "vitest";
2	import { execFileSync } from "node:child_process";
3	import { claim, createPolicy, quote } from "./claim-office.js";
4	
5	/** Runs the claim-office CLI on a scenario, returning its stdout and status. */
6	function runCli(scenario: unknown): { status: number; stdout: string; stderr: string } {
7	  try {
8	    const stdout = execFileSync("npx", ["tsx", "src/cli.ts"], {
9	      input: JSON.stringify(scenario),
10	      encoding: "utf8",
11	    });
12	    return { status: 0, stdout, stderr: "" };
13	  } catch (error) {
14	    const failure = error as { status: number; stdout: string; stderr: string };
15	    return failure;
16	  }
17	}
