19	describe("MHPCO Claim Office", () => {
20	  // --- Quote: processing fee and empty policy ---
21	  it("quotes an empty item list -- premium 5 G (processing fee only)", () => {
22	    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
23	  });
24	
25	  // --- Quote: base premiums per main item type ---
26	  it("quotes a single plain sword -- base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
27	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
28	  });
29	  it("quotes a single plain amulet -- base 60 G + 6 G first insurance + 5 G fee = 71 G", () => {
30	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
31	  });
32	  it("quotes a single plain staff -- base 80 G + 8 G first insurance + 5 G fee = 93 G", () => {
33	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }])).toBe(93);
34	  });
35	  it("quotes a single plain potion -- base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
36	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }])).toBe(49);
37	  });
38	
39	  // --- Quote: component base premiums and the building block ---
40	  it("quotes a single rune -- base 25 G component premium (25 + 2.5 + 5 -> 33 G)", () => {
41	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }])).toBe(33);
42	  });
43	  it("quotes a single moonstone -- base 25 G component premium (25 + 2.5 + 5 -> 33 G)", () => {
44	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }])).toBe(33);
45	  });
46	  it("quotes 2 runes -- base premium 50 G (no block) (50 + 5 + 5 = 60 G)", () => {
47	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }])).toBe(60);
48	  });
49	  it("quotes 3 runes -- base premium 60 G (block applies) (60 + 6 + 5 = 71 G)", () => {
50	    const runes = [{ type: "rune" }, { type: "rune" }, { type: "rune" }];
51	    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(71);
