53	  it("quotes 4 runes -- base premium 100 G (no block: block requires exactly 3) (100 + 10 + 5 = 115 G)", () => {
54	    const runes = Array.from({ length: 4 }, () => ({ type: "rune" }));
55	    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(115);
56	  });
57	  it("quotes 7 runes -- base premium 175 G (no block: block requires exactly 3) (175 + 17.5 + 5 = 197.5 -> 198 G)", () => {
58	    const runes = Array.from({ length: 7 }, () => ({ type: "rune" }));
59	    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(198);
60	  });
61	  it("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: different types) (75 + 7.5 + 5 = 87.5 -> 88 G)", () => {
62	    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
63	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(88);
64	  });
